-- CAN Algebra I Week 01; synthetic only. Never apply to production learner records.
-- Run all blocks as one transaction, after SET LOCAL can.seed_authorized=algebra1-week01.
-- Every source publication remains immutable; existing class pointer is explicitly upgraded.
DO $gate$ BEGIN
IF current_setting('can.seed_authorized',true) IS DISTINCT FROM 'algebra1-week01' THEN RAISE EXCEPTION 'Guarded Algebra I demo deployment requires explicit session setting'; END IF;
IF NOT EXISTS(SELECT 1 FROM organizations WHERE id='f1000000-0000-4000-8000-000000000002' AND slug='can-synthetic-demo' AND metadata->>'synthetic'='true') THEN RAISE EXCEPTION 'Not the synthetic ValorSchool org'; END IF;
IF NOT EXISTS(SELECT 1 FROM sections s WHERE s.id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND s.program_id='f1000000-0000-4000-8000-000000000004' AND s.code='CAN-ALG1'
 AND s.course_template_version_id IN ('bf36382c-1a56-484b-72e1-a037d3203626',md5('can-core-version:CAN-ALG1:week01:v2')::uuid) AND s.metadata->>'synthetic'='true')
THEN RAISE EXCEPTION 'Algebra I class is not the expected synthetic pilot version'; END IF;
IF NOT EXISTS(SELECT 1 FROM curriculum_adoptions a WHERE a.program_id='f1000000-0000-4000-8000-000000000004' AND a.pack_id='f9260000-0000-4000-8000-000000000001'
 AND a.pack_version_id IN ('f9260000-0000-4000-8000-000000000002',md5('can-core-pack-version:week01:v2')::uuid) AND a.status='active') THEN RAISE EXCEPTION 'Expected pack adoption not found'; END IF;
IF EXISTS(SELECT 1 FROM enrollments e WHERE e.section_id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND (e.metadata->>'synthetic') IS DISTINCT FROM 'true')
THEN RAISE EXCEPTION 'Found nonsynthetic student in class: do not reassign'; END IF;
IF EXISTS(SELECT 1 FROM curriculum_overlays ov WHERE ov.course_template_version_id='bf36382c-1a56-484b-72e1-a037d3203626' AND ov.program_id='f1000000-0000-4000-8000-000000000004')
THEN RAISE EXCEPTION 'Source version has site/class overlays requiring explicit migration'; END IF;
IF NOT EXISTS(SELECT 1 FROM section_teachers st JOIN account_person_grants g ON g.person_id=st.person_id JOIN access_accounts a ON a.id=g.account_id
 WHERE st.section_id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND g.role='teacher' AND a.email_normalized='riley.teacher@valorschool.demo') THEN RAISE EXCEPTION 'Demo teacher missing'; END IF;
END $gate$;
-- CAN_STATEMENT_BREAK
INSERT INTO course_template_versions(id,course_template_id,version,status,curriculum,published_at)
SELECT md5('can-core-version:CAN-ALG1:week01:v2')::uuid,v.course_template_id,2,'published',
jsonb_set(jsonb_set(v.curriculum,'{learning,modules}',
 COALESCE(v.curriculum->'learning'->'modules','[]'::jsonb)||jsonb_build_array('{"id":"algebra1-u01","title":"Unit 1 · Expressions, Equations, and Inequalities","lessons":[{"id":"u01-d01","title":"Day 1 · Expressions and Equivalent Forms","body":"ALGEBRA I • UNIT 1 • DAY 1 OF 5 • 55 MINUTES\nEssential question: What makes two algebraic expressions equivalent?\nLearning targets: I can distinguish expressions from equations; evaluate expressions using substitution; use distribution and collecting like terms to rewrite expressions. Standards: HSA-SSE.A.1; HSA-REI.A.1. Prerequisites: signed-number operations and the order of operations.\n\nLAUNCH (5 min)\nA school club orders 3 shirts for each of n volunteers, plus 6 extras. Two students represent the shirts as 3n + 6 and 3(n + 2). Try n = 4 and n = 10. Are the expressions equal for every n? Explain using distribution, not only a calculator.\n\nEXPLICIT INSTRUCTION (12 min)\nA variable represents a quantity. An expression such as 4x - 5 has no equality claim; an equation such as 4x - 5 = 19 asserts equality. Terms are quantities joined by addition or subtraction. Like terms share the same variable part (5x and -2x), so 5x - 2x + 7 = 3x + 7. Distribute: 2(3x - 4) = 6x - 8. The expressions 2(3x - 4) and 6x - 8 are equivalent for every x.\nWORKED EXAMPLE: Simplify 4(2x - 3) - (x + 5).\n1. Distribute: 8x - 12 - x - 5.\n2. Combine like terms: 7x - 17.\n3. Check with x = 2: original 4(4 - 3) - (2 + 5) = 4 - 7 = -3; simplified 14 - 17 = -3.\nChecking one input helps catch errors; using distribution and like terms establishes equivalence.\n\nGUIDED PRACTICE (12 min)\nA. Evaluate 2a + 3b for a = -2 and b = 5; show substituted expression first.\nB. Simplify 5(y + 2) - 3y.\nC. Explain why 4x + 4 cannot be simplified to 8x.\nCompare reasoning with a peer or teacher; explicitly name the equality property used.\n\nINDEPENDENT PRACTICE (16 min)\n1. Evaluate 3x² - 2x for x = -2.\n2. Expand and simplify 3(2p - 5) + 4p.\n3. Write two different equivalent expressions for the cost of n $8 tickets with a one-time $6 fee.\n4. Error analysis: A student rewrites 2(x + 5) as 2x + 5. Identify the mistake and fix it.\n5. Challenge: Show algebraically that (x + 3) + (2x - 4) equals 3x - 1 for every real x.\n\nEXIT TICKET (10 min)\nSimplify 2(3k - 4) + k and explain each step. Then write one sentence describing the difference between an expression and an equation.\nTurn in the exit ticket for formative feedback; it is not a grade from lesson completion alone.\n\nSELF-CHECK AND SUPPORT\nFor guided practice: A = 11; B = 2y + 10; C combines unlike terms. If you distributed to obtain 2x + 5, revisit how multiplication applies to every term inside parentheses. Extension: design two equivalent formulas for a school fundraiser.","resources":[]},{"id":"u01-d02","title":"Day 2 · Solving Equations with Equality","body":"ALGEBRA I • UNIT 1 • DAY 2 OF 5 • 55 MINUTES\nEssential question: Why does doing the same operation to both sides preserve equality?\nLearning targets: I can solve one- and two-step equations, justify each transformation, and check solutions. Standards: HSA-REI.A.1, HSA-REI.B.3.\nMaterials: pencil, scratch paper or equation editor. Prior knowledge: inverse operations.\n\nLAUNCH (6 min)\nA balance scale holds a sealed bag and 7 blocks on the left, 19 blocks on the right. What is the mass of the bag in block units? Write b + 7 = 19. Explain what happens if we remove 7 blocks from both sides.\n\nMINI-LESSON (12 min)\nAn equation gives two equal quantities. Subtracting, adding, multiplying or dividing by the same nonzero quantity on both sides preserves the solution set. To isolate x in 3x + 5 = 20:\n1. Subtract 5 on each side: 3x = 15.\n2. Divide each side by 3: x = 5.\n3. Substitute into the original: 3(5) + 5 = 20. Both sides equal 20.\nA calculation without a check can conceal sign mistakes. In -2x - 6 = 10, add 6 then divide by -2 to get x = -8. Substitute: -2(-8) - 6 = 10.\n\nGUIDED REASONING (12 min)\n1. Solve x - 9 = -2, naming the inverse operation.\n2. Solve 4y + 6 = -10. Which operation comes first and why?\n3. A peer claims 5x = 20 gives x = 100. Explain the incorrect inverse and correct it.\n4. Solve (t/3) - 2 = 4. Check by substitution.\n\nINDEPENDENT PRACTICE (15 min)\nA. 7n - 3 = 25.\nB. -3m + 4 = 19.\nC. 5 + p/2 = -1.\nD. Translate and solve: A membership costs a $12 signup fee plus $6 for each visit. A total bill is $48. How many visits? Explain why visits must be a whole number here.\nE. Write a two-step equation with solution x = -4 and show a valid solution pathway.\n\nEXIT TICKET (10 min)\nSolve -4x + 7 = 23, label each equality-preserving operation and confirm your solution in the original equation.\n\nSELF-CHECK\nGuided: 1 = 7; 2 = -4; 4 = 18. Independent: A = 4; B = -5; C = -12; D = 6 visits. The exit ticket solution is x = -4. If a check fails, retrace the first transformation where equality stopped being preserved.","resources":[]},{"id":"u01-d03","title":"Day 3 · Distributive and Multi-Step Equations","body":"ALGEBRA I • UNIT 1 • DAY 3 OF 5 • 55 MINUTES\nEssential question: How can we solve equations that contain parentheses and variables on both sides?\nLearning targets: I can distribute, gather variable terms, detect contradictions and identities, and explain why an equation may have one, no, or infinitely many solutions. Standards: HSA-REI.A.1 and HSA-REI.B.3.\n\nWARM-UP (5 min)\nSimplify 2(3x - 4) and 4x + 2x - 8. Are they equivalent? What is the difference between simplifying an expression and solving an equation?\n\nTEACHING AND WORKED EXAMPLES (15 min)\nExample 1: 3(2x - 1) = x + 12.\nDistribute: 6x - 3 = x + 12.\nSubtract x: 5x - 3 = 12.\nAdd 3: 5x = 15.\nDivide by 5: x = 3.\nVerify: 3(6 - 1) = 15 and 3 + 12 = 15.\nExample 2: 2(x + 3) = 2x + 6. Distribute: 2x + 6 = 2x + 6. Every real x works, so infinitely many solutions.\nExample 3: 2(x + 3) = 2x + 5. Distribute and subtract 2x: 6 = 5. This is false, so there is no solution.\nA zero coefficient does not automatically mean x = 0; read the remaining statement.\n\nGUIDED WORK (10 min)\nA. Solve 4x + 9 = 2x - 3 and explain each step.\nB. Solve 5(y - 2) = 2y + 8.\nC. Classify 3(x + 2) = 3x + 7 without guessing a value.\nD. Classify 4(z - 1) = 4z - 4. Describe what the final statement means.\n\nINDEPENDENT PRACTICE (15 min)\n1. Solve 2(3p + 1) = 4p + 12 and check.\n2. Solve 7 - 2a = 3(a + 4).\n3. Classify 6(t + 1) - 2 = 6t + 4.\n4. Construct an equation that has no solution and one that has infinitely many; use the same variable on both sides.\n5. A student subtracts 3x from one side only in 5x + 4 = 3x + 10. Explain the error and give a correct solution.\n\nEXIT TICKET (10 min)\nClassify 5(x - 2) + 1 = 5x - 9 and solve 3(x + 4) = x - 2. Show reasoning, not just a final number.\n\nSELF-CHECK\nGuided: A = -6; B = 6; C no solution; D infinitely many solutions. Independent: 1 = 5; 2 = -1; 3 infinitely many. Exit: first equation is an identity; second solution x = -7. Seek help if you are unsure why 0 = 0 means every number works.","resources":[]},{"id":"u01-d04","title":"Day 4 · Inequalities and Their Solution Sets","body":"ALGEBRA I • UNIT 1 • DAY 4 OF 5 • 55 MINUTES\nEssential question: How do inequalities describe ranges of possible answers?\nLearning targets: I can solve one-variable linear inequalities, reverse the comparison when multiplying or dividing by a negative, and represent solutions in words and on a number line. Standard: HSA-REI.B.3 and HSA-CED.A.1.\n\nCONTEXT (6 min)\nA club may spend at most $50. Room rental is $14 and each participant costs $4. Write 14 + 4n ≤ 50. What values of n make sense? Algebra says n ≤ 9; in this setting n is a nonnegative whole number.\n\nMINI-LESSON (12 min)\nAn inequality such as x < 7 describes many values. For x + 3 ≤ 8, subtract 3 from both sides: x ≤ 5. A number line uses a closed dot at 5 and shading to the left.\nCAUTION WITH NEGATIVES: Solve -3x > 12. Divide both sides by -3 AND reverse > to <: x < -4. Why? Multiplying an inequality by -1 reverses order: because 2 < 5, -2 > -5.\nCheck boundary and samples: x = -5 satisfies -3(-5) > 12, because 15 > 12. x = -3 does not.\n\nGUIDED PRACTICE (12 min)\n1. Solve 2x - 1 ≥ 9, and state if x = 5 is included.\n2. Solve -2y + 3 < 11, explaining the sign reversal.\n3. Describe an open dot at -1 shaded right using inequality symbols.\n4. Sketch the interval x ≥ -2 in words if a visual number line is unavailable.\n\nINDEPENDENT PRACTICE (15 min)\nA. 7 + 3t ≤ 22.\nB. -4n ≥ 16.\nC. 5 - 2p > 13.\nD. Write a real-life constraint using an inequality. Solve it and describe the domain (all reals, whole numbers, etc.).\nE. Error analysis: someone divides -2x < 8 by -2 and writes x < -4. Diagnose and correct the mistake.\n\nEXIT TICKET (10 min)\nSolve -5x + 2 ≥ 17. State if x = -3 is included. Explain one way an inequality differs from an equation.\n\nSELF-CHECK\nGuided 1: x ≥ 5, yes. 2: y > -4. 3: x > -1. Independent A: t ≤ 5; B: n ≤ -4; C: p < -4; E: x > -4. Exit: x ≤ -3, and -3 is included. If unsure about a boundary, substitute it into the original inequality.","resources":[]},{"id":"u01-d05","title":"Day 5 · Modeling and Evidence of Mastery","body":"ALGEBRA I • UNIT 1 • DAY 5 OF 5 • 55 MINUTES\nEssential question: How do we translate an unfamiliar situation into an equation or inequality and defend the answer?\nLearning targets: I can define variables, create a linear equation or inequality from a context, solve accurately, check feasibility, and explain my reasoning. Standards: HSA-CED.A.1, HSA-REI.A.1, HSA-REI.B.3.\n\nLAUNCH (5 min)\nA school has $150 for an after-school science event. The venue charges $30 and each lab kit costs $8. Write an equation to find exactly how many kits $150 buys, then determine how many kits are affordable if spending must stay at or below $150. Is it possible to buy half a kit?\n\nWORKED MODEL (12 min)\nLet k be the number of kits. Define k as a nonnegative integer.\nBudget model: 30 + 8k ≤ 150.\nSubtract 30: 8k ≤ 120.\nDivide by 8: k ≤ 15.\nConclusion: The school can purchase at most 15 kits. Check: 30 + 8(15) = 150. If k = 16, cost would be $158, too high. The domain matters: negative or fractional numbers of kits are not permitted.\n\nGUIDED TRANSFER (12 min)\n1. A student has $42 and wants notebooks at $5 each after paying a $7 delivery charge. Model, solve and interpret.\n2. A subscription costs $11 plus $3 for each extra class. Total charged is $29. Model and solve.\n3. A museum ticket costs $9 and 5 tickets cost $45. Is 5(9) = 45 an expression or equation? Explain.\n\nINDEPENDENT PRACTICE (15 min)\nA. Create an equation from: four times a number minus 7 equals 29. Solve and check.\nB. Create an inequality from: at least 20 minutes of exercise have been completed, and every round adds 6 minutes, starting from 8 minutes. Find the minimum whole number of rounds needed.\nC. Invent a school-business constraint using a fixed fee and per-student cost. Define variables, solve and critique one assumption in your model.\nD. Explain why an accurate algebraic solution sometimes needs to be rounded down and sometimes up based on context.\n\nUNIT REFLECTION AND NEXT STEPS (11 min)\nReview your work from Days 1–4. Identify a strength and an error you corrected. Complete the Unit 1 Checkpoint assignment in your class''s Assignments view. Attach no personal information in mathematical examples. The checkpoint is scored by your teacher; clicking ''Mark lesson complete'' records instructional progress but does not confer academic credit.\n\nSELF-CHECK\nGuided 1: 7 + 5n ≤ 42, so n ≤ 7 whole notebooks. 2: 11 + 3c = 29, c = 6. Independent A: n = 9. B: 8 + 6r ≥ 20 gives r ≥ 2. For C, check whether the cost rule is realistic and whether quantities must be whole numbers.","resources":[]}]}'::jsonb),true),'{learning,syllabus}',to_jsonb('CAN Algebra I (synthetic instructional pilot). Keep original Foundations preview for continuity. Unit 1, Week 1 comprises five 55-minute lessons and two teacher-graded assignments. This is a partial course and cannot award high-school graduation credit until a complete standards-aligned year, qualified instruction, assessments, and school approval are verified.'::text),true) || jsonb_build_object('unitReadiness','{"readiness":"teacher_review_required","unitId":"algebra1-u01","standards":["CCSS.HSA-SSE.A.1","CCSS.HSA-CED.A.1","CCSS.HSA-REI.A.1","CCSS.HSA-REI.B.3"],"instructionalDays":5,"suggestedMinutesPerDay":55,"source":"can-original","creditPolicy":"pending school approval; this week alone carries no course credit"}'::jsonb,'sourceVersionId',v.id::text),
now()
