INSERT INTO curriculum_pack_versions(id,pack_id,version,status,published_at,metadata)
SELECT md5('can-core-pack-version:week01:v2')::uuid,v.pack_id,2,'published',now(),
jsonb_build_object('synthetic',true,'preview',true,'notForCredit',true,'unitPilot','algebra1-week01','priorVersionId',v.id::text)
FROM curriculum_pack_versions v WHERE v.id='f9260000-0000-4000-8000-000000000002' AND v.status='published' AND v.version=1
AND EXISTS(SELECT 1 FROM course_template_versions WHERE id=md5('can-core-version:CAN-ALG1:week01:v2')::uuid AND status='published')
ON CONFLICT(id) DO NOTHING RETURNING id;
