CASE WHEN items.course_template_version_id='bf36382c-1a56-484b-72e1-a037d3203626' THEN md5('can-core-version:CAN-ALG1:week01:v2')::uuid ELSE items.course_template_version_id END,
items.position,items.metadata || '{"unitPilot":"algebra1-week01"}'::jsonb
