INSERT INTO assessments(id,section_id,title,instructions,status,points_possible,available_at,created_by_person_id,metadata)
SELECT md5('can-core-algebra1-week01-assessment:u01-formative')::uuid,s.id,'Algebra I · Unit 1 Guided Problem Set','UNIT 1 GUIDED PROBLEM SET • 20 POINTS • Submit work as text.
Explain each transformation and use the equal sign correctly. Teacher feedback guides revisions.
1. Simplify 4(2x - 3) - (x + 5). Explain two algebraic rules you used.
2. Solve 3(2x - 1) = x + 12 and verify by substitution.
3. Solve -2y + 3 < 11; explain why the inequality symbol changes or does not change.
4. A field trip charges $15 per student plus a fixed bus fee of $90. Total is $285. Define a variable, write and solve an equation for the number of students; check that the result makes sense.
Write numbered responses, include units when relevant, and explain how you checked your answers.','published',20,now(),st.person_id,'{"synthetic":true,"unitId":"algebra1-u01","courseCode":"CAN-ALG1","courseVersion":2,"teacherReviewRequired":true,"formative":true,"notForCredit":true,"rubricCriteria":[{"id":"models","label":"Define variables and build an equation or inequality","maxPoints":6,"description":"Quantity definitions and accurate mathematical model."},{"id":"reasoning","label":"Solve with justified steps","maxPoints":8,"description":"Valid inverse operations, accurate algebra and written reasoning."},{"id":"check","label":"Check, domain and interpretation","maxPoints":6,"description":"Correct substitution and feasible explanation."}],"standards":["CCSS.HSA-SSE.A.1","CCSS.HSA-CED.A.1","CCSS.HSA-REI.A.1","CCSS.HSA-REI.B.3"]}'::jsonb
FROM sections s
JOIN section_teachers st ON st.section_id=s.id AND st.role='teacher'
JOIN account_person_grants g ON g.person_id=st.person_id AND g.role='teacher' AND g.organization_id='f1000000-0000-4000-8000-000000000002'
JOIN access_accounts aa ON aa.id=g.account_id AND aa.email_normalized='riley.teacher@valorschool.demo'
WHERE s.id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND s.program_id='f1000000-0000-4000-8000-000000000004' AND s.metadata->>'synthetic'='true'
ON CONFLICT(id) DO NOTHING RETURNING id;
-- CAN_STATEMENT_BREAK
INSERT INTO assessments(id,section_id,title,instructions,status,points_possible,available_at,created_by_person_id,metadata)
SELECT md5('can-core-algebra1-week01-assessment:u01-checkpoint')::uuid,s.id,'Algebra I · Unit 1 Mastery Checkpoint','UNIT 1 CHECKPOINT • 30 POINTS • Individual written assessment.
Show your own steps and explanation. You may use ordinary scratch paper; enter the solution and reasoning in your submission.
1 (5 pts). Simplify 3(2a - 5) + 4a. Evaluate your result for a = 2 and verify against the original expression.
2 (5 pts). Solve 5(2x - 1) = 3x + 16. Identify and justify each inverse operation.
3 (5 pts). For each equation, decide whether it has one, no, or infinitely many solutions. Explain:
   A. 4(y + 2) = 4y + 8
   B. 3(z + 2) = 3z + 5
4 (5 pts). Solve -4t + 7 ≥ 19. Represent the solution in inequality notation and explain whether t = -3 is included.
5 (10 pts). A fundraiser sells notebooks for $7 each and pays a $25 setup fee. The goal is at least $200 in revenue after paying setup. Define a nonnegative integer n, write an inequality, determine the minimum notebooks needed and check your conclusion. Clearly distinguish sales revenue from net revenue.
Respond to every item. Your teacher will evaluate accuracy, reasoning and communication using the published rubric.','published',30,now(),st.person_id,'{"synthetic":true,"unitId":"algebra1-u01","courseCode":"CAN-ALG1","courseVersion":2,"teacherReviewRequired":true,"formative":false,"notForCredit":true,"rubricCriteria":[{"id":"expressions","label":"Expressions and simplification","maxPoints":5,"description":"Distributive property and combining like terms with accurate reasoning."},{"id":"equations","label":"Equation solving and justification","maxPoints":10,"description":"Correct methods, checks and distinction of one/no/all solutions."},{"id":"inequalities","label":"Inequality solving and interpretation","maxPoints":10,"description":"Correct sign reversals, boundary inclusion and contextual restrictions."},{"id":"modeling","label":"Modeling and communication","maxPoints":5,"description":"Clearly defined variables, feasible conclusion and concise explanation."}],"standards":["CCSS.HSA-SSE.A.1","CCSS.HSA-CED.A.1","CCSS.HSA-REI.A.1","CCSS.HSA-REI.B.3"]}'::jsonb
FROM sections s
JOIN section_teachers st ON st.section_id=s.id AND st.role='teacher'
JOIN account_person_grants g ON g.person_id=st.person_id AND g.role='teacher' AND g.organization_id='f1000000-0000-4000-8000-000000000002'
JOIN access_accounts aa ON aa.id=g.account_id AND aa.email_normalized='riley.teacher@valorschool.demo'
WHERE s.id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND s.program_id='f1000000-0000-4000-8000-000000000004' AND s.metadata->>'synthetic'='true'
