DO $verify$ DECLARE v_count integer; a_count integer; BEGIN
SELECT COUNT(*) INTO v_count FROM course_template_versions WHERE id=md5('can-core-version:CAN-ALG1:week01:v2')::uuid AND status='published';
SELECT COUNT(*) INTO a_count FROM assessments WHERE section_id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND metadata->>'unitId'='algebra1-u01';
IF v_count<>1 OR a_count<>2 OR NOT EXISTS(SELECT 1 FROM sections WHERE id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND course_template_version_id=md5('can-core-version:CAN-ALG1:week01:v2')::uuid)
OR NOT EXISTS(SELECT 1 FROM curriculum_adoptions WHERE program_id='f1000000-0000-4000-8000-000000000004' AND pack_version_id=md5('can-core-pack-version:week01:v2')::uuid)
THEN RAISE EXCEPTION 'Unit integration validation failed; transaction must rollback'; END IF;
END $verify$;
